insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('SL', 'default', 'Sierra Leone reference chart of accounts', '{}'::jsonb, true, 'companies', array['SL-IFRS-IS', 'SL-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in Sierra Leone. IFRS Standards are required of listed companies, banks and insurers, and IFRS for SMEs, adopted by CSAAG resolution BPR2/2009 under authority delegated by the Institute of Chartered Accountants of Sierra Leone (ICASL), is permitted for the other entities. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-based statements below, with the accounts a Sierra Leonean company actually keeps — GST input and output tax, import GST owed to the National Revenue Authority at the border, NASSIT contributions, PAYE, payroll tax, withholding tax, the 2 per cent tourism levy and excise duty payable, and the irrecoverable GST that the Act leaves with a buyer.', 'ifrs-profile')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

