insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('SL', 'SL-GST-RETURN', 'Monthly Goods and Services Tax return', array['month']::declaration_period[], 'month'::declaration_period, date '2009-09-01', null, 'Goods and Services Tax Act, 2009, s. 37(1) — a taxable person lodges a GST return for each tax period, with the National Revenue Authority in the prescribed form (s. 37(2)); s. 2 — a tax period is a month or such other period as is prescribed; s. 27 — the net amount of GST to remit for a tax period is the output tax less the input tax credits, a negative result being refundable under s. 41. The Authority''s page adds that the period is one calendar month for a taxpayer with an annual taxable turnover above Le 600,000,000 and two months for the others, a threshold stated in old leones before the 2022 redenomination and not confirmed since. The prescribed form (GST return) is filed on the ITAS portal and its box numbering could not be opened from the machine this pack was written on, so the boxes below are this pack''s own presentation of the s. 27 calculation, and the gap is recorded in this pack''s README.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Goods and Services Tax Act, 2009, s. 37(1) — the return is lodged not later than the end of the month following the tax period — and s. 38(1) — the GST payable is due on the due date for lodging the return. The Authority''s page says the same. Penalties for late filing are not modelled. A return for a two-month tax period is not modelled (see the README).', 'nra-gst', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
