values
  ('SL', 'SL-GST-RETURN', 'ZE', 'base', 'Zero-rated supplies — exports and stores', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, First Schedule — the value of exports of goods (minerals excepted) and of goods shipped as stores on vessels and aircraft leaving Sierra Leone. A reporting row of this pack.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', 'EX', 'base', 'Exempt supplies', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 9 and the Second Schedule as replaced by the Finance Act 2023 — the value of exempt supplies. A reporting row of this pack.', 'finance-act-2023'),
  ('SL', 'SL-GST-RETURN', '1S', 'base', 'Standard-rated supplies — value', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 14(3)(b) — the GST-exclusive value of the supplies taxed at 15 per cent. A reporting row of this pack.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '1S', 'tax', 'Output GST on standard-rated supplies', '{}'::jsonb, 45, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 27 — output tax on taxable supplies, net of credit notes given.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '1R', 'base', 'Imported services — value', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 24(1) — the value of a service imported from a non-resident that the recipient uses for exempt supplies, private use or entertainment. A reporting row of this pack.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '1R', 'tax', 'Output GST on imported services', '{}'::jsonb, 55, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 24(1) — the tax the recipient accounts for on such a service, included in the output tax.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '1', 'total', 'Box 1 — Output GST', '{}'::jsonb, 60, null, array['1S:tax', '1R:tax']::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 27 — total output tax of the tax period.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '2', 'base', 'Standard-rated local purchases — value', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 29 — the GST-exclusive value of the domestic purchases whose input tax is claimed. A reporting row of this pack.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '2', 'tax', 'Box 2 — Input GST on domestic purchases', '{}'::jsonb, 85, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, ss. 27 and 29 — input tax credits on domestic acquisitions, net of credit notes received.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '3', 'base', 'Imports of goods — value', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 26 — the customs value on which import GST is charged. A reporting row of this pack.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '3', 'tax', 'Box 3 — Input GST on imports', '{}'::jsonb, 95, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, ss. 29 and 39 — the GST paid on imports, claimed as input tax.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '4', 'total', 'Box 4 — Total input GST', '{}'::jsonb, 100, null, array['2:tax', '3:tax']::text[], '{}'::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 27 — total input tax credits of the tax period.', 'gst-act'),
  ('SL', 'SL-GST-RETURN', '5', 'total', 'Box 5 — GST payable or refundable', '{}'::jsonb, 110, null, array['1']::text[], array['4']::text[], null, null, false, false, null, 'Goods and Services Tax Act, 2009, s. 27 (net amount), s. 38 (payable by the due date of the return) and s. 41 (a negative amount is refundable).', 'gst-act')
on conflict (country, report_code, box, kind) do update set
