update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Goods and Services Tax Act, 2009, s. 31 and the Authority''s page on GST invoices — a GST invoice carries the number of the invoice taken from a consecutive series, and s. 34 as replaced by the Finance Act 2020 makes the invoice or the electronic cash register receipt the document of record. A consecutive series is what the text asks for; whether it must be without gap is not stated, which is why `numbering` is `sequential` and not `gapless_per_year`.',
  numbering_source_key          = 'nra-gst',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Goods and Services Tax Act, 2009, Part IV (time of supply, s. 19): the supply is made at the earliest of the events the Act lists — delivery or making available, payment, invoice. Ekwo''s closed vocabulary expresses a two-way earliest test; `earliest_of_delivery_or_payment` is the nearest value and the gap — an invoice issued ahead of both delivery and payment — is written in this pack''s README.',
  tax_point_source_key          = 'gst-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Sierra Leonean statute obliges a business to exchange a structured electronic invoice with another business in the sense Ekwo''s vocabulary gives the word: there is no Peppol authority, no published profile and no scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What Sierra Leone has instead is the electronic cash register: s. 34 of the GST Act, replaced by s. 34 of the Finance Act 2020, requires every GST-registered business to keep an electronic cash register specified by the Commissioner-General, made of a Certified Invoicing System and a Sales Data Controller that signs each receipt and sends it to the Authority''s server. That is fiscal-device reporting to the tax administration and not a peer-to-peer exchange; the gap is recorded in this pack''s README and the core is not patched to fit it.',
  einvoice_source_key           = 'nra-ecr',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'SL';
